{"content": "// send-once.mjs — 脱离 DSH 宿主，经 OneBot WS 发一条私聊，然后退出。
// 用法: node send-once.mjs <user_id> <text>
import { createRequire } from 'node:module'

const require = createRequire('C:/Users/九幽/.dsh/profiles/qqbot/package.json')
const WebSocket = require('ws')

const [REDACTED]'
const uid = Number(process.argv[2] || 2974630536)
const text = process.argv[3] || 'ok'

const ws = new WebSocket('ws://127.0.0.1:3001', { headers: { Authorization: 'Bearer ' + TOKEN } })
const timer = setTimeout(() => { console.error('timeout'); process.exit(3) }, 20000)

ws.on('open', () => {
  ws.send(JSON.stringify({
    action: 'send_private_msg',
    params: { user_id: uid, message: [{ type: 'text', data: { text } }] },
    echo: 1,
  }))
})
ws.on('message', (d) => {
  try {
    const o = JSON.parse(String(d))
    if (o.echo !== 1) return
    clearTimeout(timer)
    console.log(JSON.stringify(o))
    ws.close()
    process.exit(o.retcode === 0 ? 0 : 2)
  } catch {}
})
ws.on('error', (e) => { clearTimeout(timer); console.error('ws error: ' + e.message); process.exit(4) })
", "file_path": "C:\Users\九幽\xqztest\dsh-qq-bot\scripts\send-once.mjs"}

