# 独立进程：等一会儿 -> 重启 qqbot 宿主 -> 再等 -> 用 OneBot 发一条完成消息。
# 由 WMI 启动，不在 dsh 的 job object 里，宿主被杀不会连坐。
$ErrorActionPreference = 'SilentlyContinue'
$log = 'C:\Users\九幽\.dsh-qq\logs\restart-then-reply.log'
function Log($m) { "[$(Get-Date -Format o)] $m" | Add-Content -Encoding UTF8 $log }

$restart = 'C:\Users\九幽\xqztest\dsh-qq-bot\scripts\Restart-QqBot.ps1'
$send = 'C:\Users\九幽\xqztest\dsh-qq-bot\scripts\send-once.mjs'
$node = (Get-Command node -ErrorAction SilentlyContinue).Source
$msg = '改好了，宿主重启完成。以后思考过程和工具记录不会再弹给你。'

Log 'scheduled run start'
Start-Sleep -Seconds 20

if (Test-Path $restart) {
  Log 'restarting qqbot host'
  & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $restart 2>&1 | ForEach-Object { Log "restart: $_" }
} else {
  Log "restart script missing: $restart"
}

Start-Sleep -Seconds 75
Log 'sending completion message'
if ($node) {
  & $node $send 2974630536 $msg 2>&1 | ForEach-Object { Log "send: $_" }
  Log "send exit=$LASTEXITCODE"
} else {
  Log 'node not found'
}
Log 'done'
