/** W2-③: proactive-write audit file name, appended under mediaDir (jsonl). */
export const ACTION_AUDIT_FILE = 'qq-actions.log';
/**
 * [patch 2026-10-27] 上下文泄漏拦截标记。
 * 模型输入（<user_message> 边界）、推理原文（<thought>/<analysis>）和工具调用
 * 结构化文本都不属于聊天内容，命中即丢弃，绝不发到 QQ。
 */
export const LEAK_MARKERS = [
    '<user_message',
    '</user_message>',
    '<thought',
    '</thought>',
    '<analysis',
    '</analysis>',
    '<tool_call',
    '<function_call',
    '<usermessage',
];
/** 文本是否疑似上下文/推理泄漏。 */
export function looksLikeLeakedContext(text) {
    if (typeof text !== 'string' || text === '')
        return false;
    const head = text.slice(0, 4000);
    return LEAK_MARKERS.some((marker) => head.includes(marker));
}

